raw:
{
  "spells": [
    {
      "id": "spell_fire_01",
      "theory": "火星术把一点魔力压进干火绒的细纤维里，在纤维断口处放出短暂高热，使局部先冒烟再转为无焰的阴燃。热量只沿纤维走向传递，湿柴的水汽会吸走热量，活物的体液则让魔力无法在组织里停留，因此两者都不能成为目标。施术者需确认火绒确实干燥、松散且与手指保持三米以内的距离，否则魔力会散在空气里。",
      "casting": "拇指与食指捻起一小撮火绒，其余手指收拢成碗状，低声念出短促音节的同时用指尖轻弹火绒边缘，待烟从绒心升起便松开手势。",
      "failure": "火绒只冒出一缕青烟便熄灭，纤维被烤成焦黑却未起火；若魔力送得太急，绒心会炸开成碎屑，火星溅到附近干草上，但不会点燃湿柴或活物。",
      "counters": [
        "用水雾或湿布覆盖火绒，水汽会吸走魔力热量并阻止阴燃。",
        "在火绒周围撒一层细沙，沙粒阻隔纤维间的魔力传递，使火星无法蔓延。"
      ],
      "socialConsequences": "河谷乡约的见证人常请施术者当场点燃一小撮火绒，以确认民事承诺的见证仪式可以开始；城市公会的记录员也接受这种火星作为封蜡前的引火。猎户和厨子乐意省下打火石，但草料商担心火星落进干草堆，往往要求施术者远离货垛。港口搬运工在潮湿的码头上很少能用它点燃湿绳，因此更看重能保持火绒干燥的容器。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时火星只够点燃一小撮火绒，烟多而火弱。",
        "掌握后能在三米内稳定引燃干燥火绒，烟量明显减少。",
        "熟练者可将火星精确落在火绒中心，边缘纤维不受损。",
        "更高熟练度让阴燃转为稳定小火苗，仍只作用于干火绒。"
      ]
    },
    {
      "id": "spell_fire_02",
      "theory": "暖掌术让魔力在掌心的浅层皮肤与掌纹间来回震荡，把摩擦产生的热均匀散布到直接接触的物体表面。热量只沿接触面传导，离开手掌后便不再向远处扩散，因此揉面时面团会变温，却不会烫伤手指或烤焦案板。施术者必须让掌心完全贴合目标，若中间隔着厚布或空气，热就会散到无关的器物上。",
      "casting": "双掌合拢搓热，再轻轻贴在待暖的物体表面，保持掌根与指尖同时接触，缓慢呼吸三次，感到掌心温热均匀后移开。",
      "failure": "手掌只暖到一半，接触面出现凉热不均的斑块；若魔力送得太猛，掌心会突然发烫，但温度不会超过三十八摄氏度，接触者只会觉得不适而不会烫伤。",
      "counters": [
        "用湿布隔在手掌与目标之间，水汽会吸收热量并阻止温度传递。",
        "在目标表面涂一层薄油，油膜减缓热传导，使暖掌效果难以深入。"
      ],
      "socialConsequences": "河谷的磨坊主和面包师欢迎这种暖掌，揉面时不必再烧热水；城市里的接生婆也用它暖手再触碰产妇。但陶器商担心暖掌会让冷釉开裂，要求施术者先确认器物是否耐温。港口鱼贩用它暖僵手，却常被货主提醒别把暖掌贴在鱼箱上，以免影响鲜度。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时掌心温度不均，揉面需反复移动手掌。",
        "掌握后能在半分钟内让接触面均匀暖到适宜温度。",
        "熟练者可控制掌心温度不越过三十八摄氏度，减少不适。",
        "更高熟练度让暖掌持续更稳，仍只作用于直接接触物。"
      ]
    },
    {
      "id": "spell_fire_03",
      "theory": "烘衣术把魔力送进衣物的纤维间隙，使水分子获得足够能量脱离纤维表面，化为水汽从布面逸出。热量只在单件衣物的纤维间传递，染料与纤维本身不吸收这份能量，因此颜色和质地得以保留。施术者必须让手掌或指尖接触衣物，帆布、仓库货物或成捆布匹不在目标范围内，湿气太重时魔力会先被水吸走而无法深入。",
      "casting": "双手提起衣物两肩，让布面自然下垂，指尖沿衣缝从领口滑到下摆，同时低声念出连续音节，待布面由暗转亮便停止输送魔力。",
      "failure": "衣物只干了一半，留下深浅不一的水痕；若魔力送得太快，布面会局部过热，染料轻微褪色，但纤维不会烧焦，湿气也只是暂时被赶到衣物另一侧。",
      "counters": [
        "把衣物浸入清水再拧干，多余水分会消耗魔力，使烘干效果大减。",
        "用油布包裹衣物，油膜阻止水汽逸出，烘衣术便无法排潮。"
      ],
      "socialConsequences": "河谷的洗衣妇和旅店店主乐意请施术者烘干客人的换洗衣物，尤其在阴雨连绵的季节；城市里的裁缝也用它处理刚染色的布料，但要求先确认染料是否耐热。港口水手常靠它烘干值夜后的外套，可货主担心有人借此掩盖货损，因此港务记录员会留意烘干前后的重量变化。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时衣物干得慢，常留下局部水痕。",
        "掌握后能均匀排出一件衣物的潮气，染料基本无损。",
        "熟练者可控制烘干程度，避免过度加热使布面发硬。",
        "更高熟练度让烘干时间缩短，仍只作用于单件衣物。"
      ]
    }
  ]
}
